/// Removes a body and any retained contact history involving it.
pub fn remove(&mut self, entity: u64) {
    self.bodies.remove(&entity);
    self.previous.retain(|(a, b)| *a != entity && *b != entity);
}

/// Retains only bodies that still exist in the owning ECS world.
///
/// Scene/runtime composition uses this before each fixed step so despawned
/// entities cannot remain as invisible collision/query participants.
pub fn retain_entities(&mut self, entities: &BTreeSet<u64>) {
    self.bodies.retain(|entity, _| entities.contains(entity));
    self.previous
        .retain(|(a, b)| entities.contains(a) && entities.contains(b));
}

